fn find_minimum_total_distance(x1: i8, x2: i8, x3: i8) -> i8 {
    // Sort the three positions to find the median
    let mut xs = [x1, x2, x3];
    xs.sort();
    let median = xs[1];

    // Sum the absolute distances to the median
    xs.iter()
        .map(|&x| (x - median).abs())
        .sum()
}

